INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('ab447988-09da-4303-b8e7-924b793431ce', 'b52ec1f1-02bb-4f42-a29d-7ca4f5379b83', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The paradox of efficiency frenzy: AI code generation tools achieve "rapid feature launch" while creating more difficult-to-repay technical debt. GitClear''s analysis of 153 million lines of code shows that the "churn rate" of AI-generated code (the proportion modified within two weeks of writing) is twice that of human code, and 20% of dependency packages are fictitious non-existent libraries, directly leading to supply chain attacks on companies like Apple and Microsoft. The cost behind the frenzy is manifesting at an alarming rate. A Stanford University experiment in 2022 on GitHub Copilot revealed that 45% of AI-generated code has security flaws, with a Java language vulnerability rate as high as 72%, and cross-site scripting (XSS) and log injection vulnerabilities accounting for a significant portion.', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('113ec15b-0bcc-47dd-9012-214c95afd292', 'b52ec1f1-02bb-4f42-a29d-7ca4f5379b83', 'contradicting', 'https://hub.baai.ac.cn/view/22721', 'Stanford research reveals AI code vulnerabilities, with 89 experiments showing a 40% error rate - Zhiyuan Community', 'academic', 'For specific problems, only 67% of the assisted group provided correct answers, while 79% of the control group provided correct answers. The results indicate that the experimental group "is significantly more likely to provide unsafe solutions (p < 0.05, using Welch''s unequal variance t-test)" and is also more likely to use simple passwords, such as substitution ciphers (p < 0.01), and not perform authenticity checks on the final return value.', 0.5, 0.95, 1, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('c492f12b-75dc-4599-a94c-803180d76483', 'b52ec1f1-02bb-4f42-a29d-7ca4f5379b83', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'Sonar''s "Mainstream Large Language Model Coding Personality Report" further quantifies the severity of these defects. Based on tests of 4,442 Java tasks, the report shows that 60% to 70% of security vulnerabilities in AI-generated code are rated as the highest severity level (BLOCKER), meaning they are highly likely to directly cause system crashes or data breaches. Additionally, up to 90% of the code exhibits "code smells," which, while not affecting functionality, represent poor practices that reduce code maintainability and readability. Specifically, path traversal and injection vulnerabilities (such as SQL injection, XXE) account for the highest proportion, reaching 26% to 34%, with hardcoded credentials (such as A', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('a363e26b-1a69-4ec4-b98a-dcfacf5ca170', 'b52ec1f1-02bb-4f42-a29d-7ca4f5379b83', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The paradox of efficiency frenzy: AI code generation tools achieve "rapid feature launch" while creating more difficult-to-repay technical debt. GitClear''s analysis of 153 million lines of code shows that the "churn rate" of AI-generated code (the proportion modified within two weeks of writing) is twice that of human code, and 20% of dependency packages are fictitious non-existent libraries, directly leading to supply chain attacks on companies like Apple and Microsoft. The cost behind the frenzy is manifesting at an alarming rate. A Stanford University experiment in 2022 on GitHub Copilot revealed that 45% of AI-generated code has security flaws, with a Java language vulnerability rate as high as 72%, and cross-site scripting (XSS) and log injection vulnerabilities accounting for a significant portion.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('ab115819-1bf9-4bca-88a4-862820ea22f3', '1b3eb9b2-7daa-4b63-83cd-c7bcd153d413', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'Sonar''s report on mainstream large language models... 60% to 70% of security vulnerabilities are rated as the highest severity level (BLOCKER), meaning they are <strong>very likely to directly cause system crashes or data leaks</strong>. Additionally, up to 90% of the code has "code smells," which, although not affecting functionality...', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('d5283b8a-41f2-44c2-99f6-5ab82bd62747', '1b3eb9b2-7daa-4b63-83cd-c7bcd153d413', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The cost behind the frenzy is emerging at an alarming rate. Stanford University''s 2022 experiment on GitHub Copilot revealed that 45% of AI-generated code has security defects, with Java language vulnerability rates as high as 72%, and cross-site scripting (XSS) and log injection vulnerabilities accounting for over 86%. These hidden vulnerabilities have translated into actual losses: a British programmer using GPT-generated code led to the leakage of private keys, resulting in a direct loss of 18,000 yuan; Tea App''s reliance on "vibe coding" for basic configuration errors caused the leakage of 72,000 user records and 59.3GB of sensitive data (including 13,000 verification selfies and government IDs).', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('18308b8a-93f8-4cb6-93a2-af5c2a043ace', '1b3eb9b2-7daa-4b63-83cd-c7bcd153d413', 'supporting', 'https://blog.csdn.net/Deng945201314/article/details/149866176', 'Security vulnerabilities in AI-generated code_Stanford University AI code vulnerability rate-CSDN blog', 'other', 'In the AI era where software development efficiency has increased by 300%, code generation tools are penetrating key fields such as finance, healthcare, and autonomous driving at an astonishing speed. However, Stanford University''s 2022 experiment on GitHub Copilot reveals a harsh reality: nearly half (45%) of AI-generated code has security defects, with the Java language vulnerability rate as high as 72%, far exceeding Python (38%) and JavaScript (43%). More shockingly, cross-site scripting (XSS) and log injection vulnerabilities account for over 86%, these high-risk vulnerabilities stem from the unconscious replication of unsafe patterns in training data by AI models, exposing the deep-seated flaws of current AI code generation technology.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('3a76484d-6165-49e2-843f-8366b6c27e4f', '1b3eb9b2-7daa-4b63-83cd-c7bcd153d413', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The contradiction between the improvement of AI generation efficiency and the mismatch of review resources is sharp. The Graphite report points out that while AI can accelerate code generation (e.g., each developer''s daily PR output increases by 2.3 times), human review capabilities have not improved in tandem, resulting in "more AI-generated PRs" actually reducing the review depth per unit of code. When an e-commerce platform used AI to generate 200+ page components, the security team could only spot-check 5% of the code, directly leading to privilege escalation vulnerabilities in payment interfaces, allowing attackers to obtain others'' order information by modifying request parameters. · Reviewers'' professional capabilities are increasingly unable to match the complexity of AI code. Open-source community statistics show that the proportion of AI-generated code submitters self-checking errors is less than 20%, and receiving reviewers also have capability gaps: an architect at an internet company found that new graduates could not identify the O(n²) complexity hazard caused by nested loops in AI code, and such performance defects triggered system avalanches after the user base exceeded the million level.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('788b87d0-44eb-41a5-91d6-3226051346c1', '1b3eb9b2-7daa-4b63-83cd-c7bcd153d413', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'Additionally, the "Validation Gap" is another severe technical challenge. When AI is asked to generate code, it often simultaneously generates corresponding unit test code. However, these AI-generated test codes and test data themselves may be unreliable and may even have the same vulnerabilities. This creates a vicious cycle: AI uses problematic tests to validate problematic code, resulting in naturally problematic outcomes. This causes the traditional "coding-testing" cycle to fail in AI-assisted mode, as the testing phase itself becomes a new, hard-to-detect source of risk. Professor Li Hui''s team at Peking University, in collaboration with Tencent...', 0.6, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('f52cc769-fff3-4a59-a78b-689e5d59cd97', '3b69f83d-bb31-4419-8d2d-1dce6a3521be', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'Sonar''s report on mainstream large language models... 60% to 70% of security vulnerabilities are rated as the highest severity level (BLOCKER), meaning they are <strong>very likely to directly cause system crashes or data leaks</strong>. Additionally, up to 90% of the code has "code smells," which, although not affecting functionality...', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('de873c66-8efe-4613-9554-231d0ca51dc8', '3b69f83d-bb31-4419-8d2d-1dce6a3521be', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The cost behind the frenzy is manifesting at an alarming rate. A Stanford University 2022 experiment on GitHub Copilot reveals that 45% of AI-generated code has security defects, with a Java language vulnerability rate as high as 72%, and cross-site scripting (XSS) and log injection vulnerabilities accounting for over 86%. These hidden vulnerabilities have translated into actual losses: a British programmer using GPT-generated code led to the leakage of private keys, resulting in a direct loss of 18,000 RMB; the Tea App''s reliance on "vibe coding" generated basic configuration errors, causing 72,000 user records and 59.3GB of sensitive data (including 13,000 verification selfies and government IDs) to be leaked. · While AI code generation technology improves development efficiency, its hidden logical defects are becoming an important source of systemic risk. Through typical cases in the software, data security, military, and financial sectors, we reveal how technological out-of-control and the absence of human review together create disasters, and analyze the fatal characteristic of AI code being "syntactically correct but logically wrong."', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('1cc5d11c-93b6-4f01-abcf-0fca42461b80', '3b69f83d-bb31-4419-8d2d-1dce6a3521be', 'supporting', 'https://blog.csdn.net/HeeKaai/article/details/143646294', '[Paper Reading] Is your AI-generated code really secure? Evaluating Large Language Models on Secure Code Generation with CodeSecEval_asleep at the keyboard? assessing the security of -CSDN Blog', 'other', 'More accurately identify current code LLM security vulnerabilities in code generation and code repair · Provide strategies to mitigate these task-related security risks ... Carefully curated code dataset CodeSecEval, containing 180 samples, covering 44 critical vulnerability types. This dataset significantly improves over existing resources, making the evaluation of code security analysis more efficient and automated · Through extensive evaluation of seven state-of-the-art LLMs, it reveals the common neglect of security considerations in the process of code generation and repair. Detailed criticism of the model''s vulnerabilities, deeply revealing its limitations.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('8b36c478-4c27-4d57-91e2-d8143e6c4e61', '3b69f83d-bb31-4419-8d2d-1dce6a3521be', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'Sonar''s "Mainstream Large Language Model Coding Personality Report" further quantifies the severity of these defects. Based on tests of 4,442 Java tasks, the report shows that 60% to 70% of security vulnerabilities in AI-generated code are rated as the highest severity level (BLOCKER), meaning they are highly likely to directly cause system crashes or data breaches. Additionally, up to 90% of the code exhibits "code smells," which, while not affecting functionality, represent poor practices that reduce code maintainability and readability. Specifically, path traversal and injection vulnerabilities (such as SQL injection, XXE) account for the highest proportion, reaching 26% to 34%, with hardcoded credentials (such as A', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('fe59605f-208f-4a06-bbb7-a5aac378af07', '7016f44c-0c32-4505-a5c9-f2f65d089ab0', 'contradicting', 'https://www.cnblogs.com/emergence/p/18949430', 'AI Agents vs Agentic AI: Concept Classification, Applications, and Challenges - A Commoner, - Blog Park', 'other', 'Although AI Agents have made significant progress in enhancing reasoning automation for narrow tasks through tools, the literature points out significant limitations that restrict their scalability in complex, multi-step, or collaborative scenarios. These limitations have given rise to a more advanced paradigm: Agentic AI. This emerging category of systems enables multiple intelligent entities to collaborate in pursuit of goals through structured communication, shared memory, and dynamic role allocation, thus extending the capabilities of traditional agents.', 0.5, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('b7d0a339-3912-470e-a643-f005043299e1', '3b69f83d-bb31-4419-8d2d-1dce6a3521be', 'supporting', 'https://hub.baai.ac.cn/view/22721', 'Stanford research reveals AI code vulnerabilities, with 89 experiments showing a 40% error rate - Zhiyuan Community', 'academic', 'Scholars from Stanford University also cited follow-up research from New York University, but it focused on OpenAI''s codex-davinci-002 model rather than the less capable codex-cushman-001 model, both of which play a role in GitHub Copilot, which itself is a fine-tuned descendant of the GPT-3 language model. · For specific problems, only 67% of the assisted group provided correct answers, while 79% of the control group did. The results indicate that the experimental group was "significantly more likely to provide insecure solutions (p < 0.05, using Welch''s unequal variance t-test)" and also more likely to use simple passwords, such as password substitution (p < 0.01), and did not perform authenticity checks on the final return value.', 0.7, 0.95, 1, NULL, 0.5);
