INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('c84c8139-2cdb-4e8d-959d-441f6cd79837', '8795c92b-dac6-41c7-8424-d6f59b12d47c', 'contradicting', 'https://www.goupsec.com/news/15486.html', 'Beware of AI code mountains, 36% of Copilot-generated code has vulnerabilities - GoUpSec', 'other', 'The so-called software security debt is usually... prevalent in applications and 71% of organizations, and the surge in AI-generated code will exacerbate security debt issues and pose significant risks to the software supply chain. ...', 0.5, 0.4, 4, NULL, 0.5);
