INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('a54f941d-a3a0-4d95-b32f-99e009748a0e', '4274d6a0-c06c-4f9b-be0c-a6f07a6b9fe0', 'supporting', 'https://m.ofweek.com/ai/2026-01/ART-201700-8420-30678222.html', '2026 Agentic AI Ten Development Trends: Technological Breakthroughs and Commercial Implementation Panorama - OFweek Artificial Intelligence Network', 'other', 'Short-term memory enhancement: Context window expansion technology allows the Agent to handle longer task sequences, expanding from the traditional thousands of tokens to tens of thousands of tokens, supporting end-to-end execution of complex business processes. OpenAI is actively advancing related research, and personal assistant-level memory capabilities are expected to be initially realized by 2026. · Long-term memory architecture: Systems like Memory Bear build a human-like memory architecture, integrating multimodal information perception, dynamic memory maintenance, and adaptive cognitive services, achieving a full-chain reconstruction of LLM memory mechanisms. This architecture includes short-term memory (for current task context) and long-term memory (for storing past successful experiences and lessons learned), enabling AI Agents to learn from historical interactions and continuously optimize their decision paths.', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('e6179e22-4d8d-4c0e-a2d9-40c16b3c9f80', '4274d6a0-c06c-4f9b-be0c-a6f07a6b9fe0', 'supporting', 'https://blog.ppio.com/yi-wen-kan-dong-agentde-9chong-ji-yi-xi-tong-aizhuan-lan/', 'Understanding the 9 "memory systems" of Agents in one article | AI Column', 'other', 'For an AI Agent, "memory" refers to its ability to retain information, context, user preferences, and task details over multiple interactions. Just like an assistant needs to remember the tasks assigned by the boss yesterday, an AI Agent must also "have memory" to truly complete continuous tasks. · However, AI does not naturally have memory; it only has a "context window" — which means every time we interact with the model, we have to "resend" the previous conversation for it to "see the past." · The problem arises: the context window has a length limit, and too much information cannot fit; repeated sending also leads to high token costs. · Therefore, researchers and developers have invented many different "memory strategies" to make the Agent smarter and more resource-efficient.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('f570711c-b299-428c-af24-aae29622db2f', 'f3243a2d-bef8-4ae2-a90c-5e7003f03e45', 'supporting', 'https://www.secrss.com/articles/80089', 'One-third of AI code enters production environments without review - Security Reference | Cybersecurity Knowledge Base for Decision Makers.', 'other', 'This is a shocking statistic, and it reveals a disturbing trend: a large amount of insufficiently reviewed AI code is directly entering the production environment.', 0.5, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('0043e460-9ced-4ed6-802c-60a76a79aa37', '4274d6a0-c06c-4f9b-be0c-a6f07a6b9fe0', 'supporting', 'https://aws.amazon.com/cn/blogs/china/agentic-ai-infrastructure-deep-practice-experience-thinking-series-three-best-practices-for-agent-memory-module/', 'Agentic AI Infrastructure Practice Experience Series (Part 3): Best Practices for Agent Memory Modules | Amazon AWS Official Blog', 'other', 'Continuous knowledge update: Achieving self-improvement and knowledge update through storing experiences of interaction with the environment and users; · Personalized service: Recording user preferences and historical interactions to provide customized responses; · Complex task support: Tracking the progress and intermediate results of multi-Agent tasks to ensure coherent completion and optimize decision-making; · Enhancing interaction quality: Maintaining context coherence, supporting in-depth reasoning, and learning from mistakes through reflection mechanisms. · The memory system of intelligent agents is mainly divided into short-term memory and long-term memory.', 0.7, 0.4, 4, NULL, 0.5);
