INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('4da818cf-caa2-44b4-9eb3-4618d32b97d6', 'b7c8be72-4044-4cac-8482-1ec271683822', 'supporting', 'https://www.freebuf.com/news/434891.html', 'The main security risks faced by generative AI and their solutions - FreeBuf Network Security Industry Portal.', 'other', 'In the CSET assessment, nearly half of the code snippets generated by five mainstream models, including open-source tools like GPT-4 and Code Llama, contained at least one security-related defect. Some of these defects are severe enough to cause buffer overflows or unauthorized memory access. · These are not just bad practices—they are exploitable entry points. · This is the trickiest part. Many developers overly trust AI-generated code. In CSET''s research, most participants believed these codes were safe—even when they were not. This is automation bias. It leads to unsafe code being directly copied into the production environment.', 1.0, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('71f61015-8aa0-4107-a22f-5e9ca0bb0317', 'bc913084-d62e-42cd-bfd5-d47c8872d6d7', 'contradicting', 'https://www.secrss.com/articles/87726', 'New threats in the AI Agent ecosystem: Weaponization of Skills and complete attack chain analysis - Security Insider | A cybersecurity knowledge base for decision-makers.', 'other', 'But the problem also stems from this: Skills are mostly third-party developed code but have actual system access permissions, and many Skills installation steps guide users to execute "terminal paste commands," "download and run binary files," "configure environment variables," etc. In the eyes of hackers, this seemingly normal operation guide becomes a perfect social engineering attack vector, making the Skills ecosystem both a productivity tool and a hotbed for malware authors. To identify new abuse patterns of OpenClaw Skills, VirusTotal has added native support for OpenClaw Skills packages (including ZIP format) in its Code Insight feature.', 0.2, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('1a39585b-d3e1-47d9-92ec-8348c60d0f1a', 'bc913084-d62e-42cd-bfd5-d47c8872d6d7', 'supporting', 'https://aws.amazon.com/cn/blogs/china/privacy-and-security-of-agent-applications/', 'Agentic AI Infrastructure Practice Experience Series (8): Privacy and Security of Agent Applications | Amazon AWS Official Blog', 'other', 'In the new software supply chain framework of the MCP ecosystem, AI clients (such as IDE plugins or desktop applications) can reference or connect to any MCP server created and hosted by anonymous developers worldwide as needed. The code quality, security practices, and maintenance status of these servers vary, and they often lack any form of official certification, audit, or trust endorsement. When users or organizations integrate a new MCP server, they are essentially introducing a series of new, unverified dependencies into their systems, which contrasts sharply with the traditional software development practice of strictly reviewing third-party libraries. Therefore, the entire MCP ecosystem...', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('fec45477-0930-4d60-af9b-42d3362581c5', 'bc913084-d62e-42cd-bfd5-d47c8872d6d7', 'contradicting', 'https://www.80aj.com/2026/02/05/ai-agent-security-flaws/', 'Security vulnerabilities in AI Agents: 90% of developers have ignored them.', 'other', 'Last year, an AI customer service Agent was hacked, leaking personal information of 50,000 users. The issue was not with the model, but with developers neglecting basic security measures. The security issues of AI Agents are more complex than traditional applications because they have autonomy. Vulnerability one: excessive permissions Current situation: Most Agents ...', 0.4, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('7310b4a1-e1e8-485f-a3bb-a5f4c22e2ee3', 'bc913084-d62e-42cd-bfd5-d47c8872d6d7', 'supporting', 'https://developer.nvidia.com/blog/how-code-execution-drives-key-risks-in-agentic-ai-systems/', 'How Code Execution Drives Key Risks in Agentic AI Systems | NVIDIA Technical Blog', 'other', 'AI-driven applications are evolving from passive tools to agentic systems that generate code, make decisions, and take autonomous actions. This shift introduces a critical security challenge.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('f17a7366-59c6-4ace-ba57-fe3e456c6ee3', 'bc913084-d62e-42cd-bfd5-d47c8872d6d7', 'supporting', 'https://aws.amazon.com/cn/blogs/china/privacy-and-security-of-agent-applications/', 'Agentic AI Infrastructure Practice Experience Series (8): Privacy and Security of Agent Applications | Amazon AWS Official Blog', 'other', 'In the new software supply chain framework of the MCP ecosystem, AI clients (such as IDE plugins or desktop applications) can reference or connect to any MCP server created and hosted by anonymous developers worldwide as needed. The code quality, security practices, and maintenance status of these servers vary, and they often lack any form of official certification, audit, or trust endorsement. When users or organizations integrate a new MCP server, they are essentially introducing a series of new, unverified dependencies into their systems, which contrasts sharply with the traditional software development practice of strictly reviewing third-party libraries. Therefore, the entire MCP ecosystem...', 0.7, 0.4, 4, NULL, 0.5);
