INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('0590c376-b7dd-450b-a8d2-2cd41643d969', '6fc1bd17-2fb3-4bd5-91c0-d5af258959dd', 'supporting', 'https://www.secrss.com/articles/80089', 'One-third of AI code enters production environments without review - Security Reference | Cybersecurity Knowledge Base for Decision Makers.', 'other', 'Developers are not unaware of this: nearly 80% (79.2%) of developers believe AI will exacerbate malware threats in open-source software, with 30% believing the risk will "significantly increase." Only 13% of developers are optimistic about AI on the defense front. ... In today''s world where AI has become a main developer, code review mechanisms still rely on human effort. A Cloudsmith report reveals that one-third of developers do not conduct pre-deployment reviews of AI-generated code, meaning a large amount of unverified code is being put into use, posing a significant threat to the software supply chain.', 0.8, 0.4, 4, NULL, 0.5);
