INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('8e0cdca1-6213-4710-8705-56f9cbb0ee94', '801f6b69-2e84-4727-80d6-f2ab542c5f07', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'The stability of the financial and securities markets has not been spared from the impact of lax AI review. On April 7, 2025, a market upheaval triggered by high-frequency trading algorithms occurred on the Warsaw Stock Exchange in Poland, causing the WIG20 index to plummet by 7% intraday and triggering a trading halt of about 75 minutes. Although the specific technical details were not detailed in the materials, such events usually stem from the failure of algorithm logic under specific market conditions, which can often be traced back to defects in the underlying code. If these codes were generated by AI without strict review, the root of the problem points to the security blind spot of AI-assisted programming. Additionally, in 2023, Samsung Electronics', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('bd672b76-0932-451b-b616-98e1eaa575ac', '801f6b69-2e84-4727-80d6-f2ab542c5f07', 'supporting', 'https://www.secrss.com/articles/80089', 'One-third of AI code enters production environments without review - Security Reference | Cybersecurity Knowledge Base for Decision Makers.', 'other', 'In an era where AI has become the main developer, code review mechanisms still rely on human effort. A Cloudsmith report reveals that one-third of developers do not conduct pre-deployment reviews of AI-generated code, meaning a large amount of unverified code is being put into use, posing a significant threat to the software supply chain.', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('7a293e2a-06e7-4800-9fb2-dfe03e0f8411', '801f6b69-2e84-4727-80d6-f2ab542c5f07', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'Summary of risk transmission paths: The inherent defects of AI code generation form systemic risk through three levels of transmission—first, the probability prediction mechanism leads to the inability to guarantee logical correctness; second, insufficient understanding of business and architecture causes code to deviate from actual needs; finally, quality degradation and hidden errors reduce system robustness, causing catastrophic consequences such as performance collapse (e.g., query performance dropping 60 times), data errors (distributed transaction inconsistency), and security vulnerabilities (unauthorized access). This transmission chain highlights: Human review must deeply intervene in complex logical design, rather than just perform syntax-level checks.', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('d28794f9-8fb0-4838-a549-0b0a0c2befdf', '801f6b69-2e84-4727-80d6-f2ab542c5f07', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'Excessive trust in AI-generated content by humans is forming a systemic cognitive bias. Stanford University''s 2025 experiment shows that 79% of developers would misjudge AI-generated unsafe code as safe. This "verification illusion" stems from blind trust in AI output—developers focus more on whether the code "can run" rather than "is it safe," forming a "Vibe Coding" trap: fully relying on AI-generated logic, not reviewing internal implementation, accepting code through superficial functional testing, ultimately accumulating a large amount of "trust debt."', 0.8, 0.4, 4, NULL, 0.5);
