INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('a87be810-ed01-43d3-a54a-ceaba9322733', 'bb34fb6d-32d4-40d8-8da6-5d75b2e660ad', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'Excessive trust in AI-generated content by humans is forming systemic cognitive bias. A Stanford University 2025 experiment shows that 79% of developers would misjudge AI-generated unsafe code as safe, this "verification illusion" stems from blind trust in AI output—developers focus more on whether the code "can run" rather than "is it safe," forming a "Vibe Coding" trap: completely relying on AI-generated logic, not reviewing internal implementation, accepting code through superficial functional testing, ultimately accumulating a large amount of "trust debt." · The improvement in AI generation efficiency and the mismatch of review resources form a sharp contradiction. The Graphite report points out that although AI can accelerate code generation (such as every', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('315ef879-8369-4b60-9f84-281ec0e50f59', 'bb34fb6d-32d4-40d8-8da6-5d75b2e660ad', 'contradicting', 'https://www.secrss.com/articles/80089', 'One-third of AI code enters production environments without review - Security Reference | Cybersecurity Knowledge Base for Decision Makers.', 'other', 'The biggest contradiction and threat currently facing software development is that the speed of human review can no longer keep up with the speed of AI-generated code. · According to Cloudsmith''s latest "2025 Artifact Management Report," AI code generation tools have become important participants in the development process. Among developers using AI programming, 42% stated...', 0.5, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('9873c39e-6581-4c24-a597-e39a3935efe9', 'bb34fb6d-32d4-40d8-8da6-5d75b2e660ad', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'In the field of infrastructure configuration, disasters caused by human review negligence are equally shocking. In 2025, an engineer, for convenience, used the AI large language model (LLM) tool Claude to generate Terraform code for deploying PostgreSQL RDS instances but did not conduct a strict review. As a result, the AI-generated code included an ingress rule allowing access from all IP addresses from 0.0.0.0/0, directly exposing the production database to the public internet, becoming a huge security risk. This P0-level major incident resulted in emergency response costs of up to $50,000 and triggered weeks of regulatory challenges, with the involved engineer facing the risk of dismissal. This case profoundly illustrates that even seemingly harmless automated tasks, once involving infrastructure security configuration, can instantly collapse a system''s security defenses if lacking meticulous oversight by human experts.', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('1014692c-a460-4146-a8fc-72990bc43bf4', 'bb34fb6d-32d4-40d8-8da6-5d75b2e660ad', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'Risk transmission path summary: The inherent defects of AI code generation form systemic risks through a three-level transmission—first, the probability prediction mechanism leads to the inability to guarantee logical correctness; second, insufficient understanding of business and architecture causes the code to deviate from actual requirements; finally, quality degradation and hidden errors reduce system robustness, triggering catastrophic consequences such as performance crashes (e.g., query performance dropping 60 times), data errors (distributed transaction inconsistencies), and security vulnerabilities (privilege escalation). This transmission chain highlights: human review must deeply intervene in complex logic design, rather than merely perform syntax-level checks. · In the context of the widespread adoption of AI code generation technology, the failure of human review mechanisms is not caused by a single factor but is a systemic issue resulting from cognitive biases, process design flaws, and professional capability degradation. This article constructs a "psychology-process-capability" three-dimensional analysis framework to reveal the logic of the failure of human review responsibilities in the AI era.', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('22558fc8-0e9f-41cd-9ae6-fa346cc60799', 'b8bccbb4-8431-4ef6-8b9e-44623ea43d70', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The cost behind the frenzy is emerging at an alarming rate. Stanford University''s 2022 experiment on GitHub Copilot revealed that 45% of AI-generated code has security defects, with Java language vulnerability rates as high as 72%, and cross-site scripting (XSS) and log injection vulnerabilities accounting for over 86%. These hidden vulnerabilities have translated into actual losses: a British programmer using GPT-generated code led to the leakage of private keys, resulting in a direct loss of 18,000 yuan; Tea App''s reliance on "vibe coding" for basic configuration errors caused the leakage of 72,000 user records and 59.3GB of sensitive data (including 13,000 verification selfies and government IDs).', 0.8, 0.4, 4, NULL, 0.5);
