INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('14c80f4b-07f7-4e76-bedf-83bf2934eb2f', 'b8bccbb4-8431-4ef6-8b9e-44623ea43d70', 'supporting', 'https://blog.csdn.net/weixin_43172311/article/details/147104833', 'Nine security risks of AI writing code - CSDN blog on the disadvantages of AI-generated code.', 'other', 'When your AI assistant helps you write beautiful code, it may hide these unexpected "minefields." Let''s use the simplest language to uncover the real risks behind those technical terms. · Just like a northerner going south for the first time might "get heat," AI-generated code may not adapt to your system environment. ‌Real case‌: A company''s AI-generated payment interface code failed to account for the company''s internal key management rules, rendering payment verification ineffective.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('a84aa51c-f47b-4da9-b215-c25c64ba42a3', 'b8bccbb4-8431-4ef6-8b9e-44623ea43d70', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The cost behind the frenzy is emerging at an alarming rate. Stanford University''s 2022 experiment on GitHub Copilot revealed that 45% of AI-generated code has security defects, with Java language vulnerability rates as high as 72%, and cross-site scripting (XSS) and log injection vulnerabilities accounting for over 86%. These hidden vulnerabilities have translated into actual losses: a British programmer using GPT-generated code led to the leakage of private keys, resulting in a direct loss of 18,000 yuan; Tea App''s reliance on "vibe coding" for basic configuration errors caused the leakage of 72,000 user records and 59.3GB of sensitive data (including 13,000 verification selfies and government IDs).', 0.8, 0.4, 4, NULL, 0.5);
