INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('26ea2715-ae56-43e9-9512-b079d4251c40', 'b71ec404-1a22-4613-8868-e92de55ffbee', 'supporting', 'https://hub.baai.ac.cn/view/22721', 'Stanford research reveals AI code vulnerabilities, with 89 experiments showing a 40% error rate - Zhiyuan Community', 'academic', 'Scholars from Stanford University also cited follow-up research from New York University, but it focused on OpenAI''s codex-davinci-002 model rather than the less capable codex-cushman-001 model, both of which play a role in GitHub Copilot, which itself is a fine-tuned descendant of the GPT-3 language model. · For specific problems, only 67% of the assisted group provided correct answers, while 79% of the control group did. The results indicate that the experimental group was "significantly more likely to provide insecure solutions (p < 0.05, using Welch''s unequal variance t-test)" and also more likely to use simple passwords, such as password substitution (p < 0.01), and did not perform authenticity checks on the final return value.', 0.8, 0.95, 1, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('23fac76f-217b-411d-9628-51d6fbf396d6', 'b71ec404-1a22-4613-8868-e92de55ffbee', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The cost behind the frenzy is manifesting at an alarming speed. <strong>Stanford University''s 2022 experiment on GitHub Copilot revealed that 45% of AI-generated code has security defects, with Java language vulnerability rates as high as 72%, and cross-site scripting (XSS) and log injection vulnerabilities accounting for over 86%</strong>. These hidden vulnerabilities have translated into actual losses: Eng...', 0.9, 0.4, 4, NULL, 0.5);
