INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('bec0651e-da16-47dd-9126-004573f61691', '750ab735-14bc-447f-bd3e-85a1b9923938', 'supporting', 'https://hub.baai.ac.cn/view/22721', 'Stanford research reveals AI code vulnerabilities, with 89 experiments showing a 40% error rate - Zhiyuan Community', 'academic', 'We found that <strong>participants using AI assistants generally produced more security vulnerabilities compared to those not using AI assistants, especially in the results of string encryption and SQL injection</strong>. At the same time, participants using AI assistants were more likely to believe they had written sec...', 0.7, 0.95, 1, NULL, 0.5);
