INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('eb1a92ce-07e3-4ae2-aaea-1b77be21f585', '750ab735-14bc-447f-bd3e-85a1b9923938', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'Sonar''s "Mainstream Large Language Model Coding Personality Report" further quantifies the severity of these defects. Based on tests of 4,442 Java tasks, the report shows that 60% to 70% of security vulnerabilities in AI-generated code are rated as the highest severity level (BLOCKER), meaning they are highly likely to directly cause system crashes or data breaches. Additionally, up to 90% of the code exhibits "code smells," which, while not affecting functionality, represent poor practices that reduce code maintainability and readability. Specifically, path traversal and injection vulnerabilities (such as SQL injection, XXE) account for the highest proportion, reaching 26% to 34%, with hardcoded credentials (such as A', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('242508ab-1798-4e0a-9de9-287d3d13dc4a', '750ab735-14bc-447f-bd3e-85a1b9923938', 'contradicting', 'https://blog.csdn.net/Deng945201314/article/details/149866176', 'Security vulnerabilities in AI-generated code_Stanford University AI code vulnerability rate-CSDN blog', 'other', 'In the AI era where software development efficiency has increased by 300%, code generation tools are penetrating key fields such as finance, healthcare, and autonomous driving at an astonishing speed. However, Stanford University''s 2022 experiment on GitHub Copilot reveals a harsh reality: nearly half (45%) of AI-generated code has security defects, with the Java language vulnerability rate as high as 72%, far exceeding Python (38%) and JavaScript (43%). More shockingly, cross-site scripting (XSS) and log injection vulnerabilities account for over 86%, these high-risk vulnerabilities stem from the unconscious replication of unsafe patterns in training data by AI models, exposing the deep-seated flaws of current AI code generation technology.', 0.5, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('96dfca0f-54f3-4af5-b842-6434841df168', '3180b2b5-ff30-4f3c-aa6f-6b83baeba497', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The paradox of efficiency frenzy: AI code... supply chain attacks. · The cost behind the frenzy is manifesting at an alarming rate. <strong>Stanford University''s 2022 experiment on GitHub Copilot revealed that 45% of AI-generated code has security defects</strong>, with Java language vulnerability rates as high as 72%, cross-site scripting (XSS), and log injection...', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('006ba06e-1396-449f-aa00-411ba849b30b', '3180b2b5-ff30-4f3c-aa6f-6b83baeba497', 'contradicting', 'https://hub.baai.ac.cn/view/22721', 'Stanford research reveals AI code vulnerabilities, with 89 experiments showing a 40% error rate - Zhiyuan Community', 'academic', 'AI writes code, saving time and effort. But recently, computer scientists at Stanford University found that code written by programmers using AI assistants is actually riddled with vulnerabilities. They discovered that programmers assisted by AI tools like Github Copilot write code that is less secure and accurate than code written independently.', 0.5, 0.95, 1, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('e02e32f4-adf5-4886-b766-1dad82b1d48a', '3180b2b5-ff30-4f3c-aa6f-6b83baeba497', 'supporting', 'https://cloud.tencent.com/developer/article/2207313', '89 experiments, with an error rate as high as 40%! Stanford''s first large-scale survey reveals AI code writing vulnerabilities - Tencent Cloud Developer Community - Tencent Cloud', 'other', 'AI writes code, saving time and effort. · But recently, computer scientists at Stanford University found that code written by programmers using AI assistants is actually full of vulnerabilities?', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('2e219d1a-2152-4c48-bb64-9b564d8a51db', '3180b2b5-ff30-4f3c-aa6f-6b83baeba497', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The probabilistic prediction mechanism of AI models makes it difficult to perform strict logical reasoning, specifically manifesting as weak boundary condition handling and hidden logical errors. In a binary search algorithm generation case, AI failed to correctly handle integer division logic (e.g., mid = (low + high) / 2 without considering integer overflow risk, or not using low + (high - low) / 2 optimization), leading to silent failures under specific inputs—such errors are only triggered at extreme values (e.g., array length being the maximum integer), making them difficult to discover in regular testing.', 0.9, 0.4, 4, NULL, 0.5);
