INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('f6c23a36-0625-4f27-b0e1-7ccc2474c8bc', '08ab6cce-2975-48f6-991e-93c5d8d711ff', 'supporting', 'https://www.secrss.com/articles/80089', 'One-third of AI code enters production environments without review - Security Reference | Cybersecurity Knowledge Base for Decision Makers.', 'other', 'In an era where AI has become the main developer, code review mechanisms still rely on human effort. A Cloudsmith report reveals that one-third of developers do not conduct pre-deployment reviews of AI-generated code, meaning a large amount of unverified code is being put into use, posing a significant threat to the software supply chain.', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('5fb5c07c-8593-4e61-ae4e-25eb9d185ce2', '08ab6cce-2975-48f6-991e-93c5d8d711ff', 'contradicting', 'https://www.goupsec.com/news/19402.html', 'One-third of AI code enters production without review - GoUpSec', 'other', 'The biggest contradiction and threat currently facing software development is that the speed of human review can no longer keep up with the speed of AI-generated code. · According to Cloudsmith''s latest "2025 Artifact Management Report," AI code generation tools have become important participants in the development process. Among developers using AI programming, 42% stated...', 0.5, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('e6ca54c8-4787-4cde-85fd-5b94cbefe61f', '08ab6cce-2975-48f6-991e-93c5d8d711ff', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'The contradiction between the improvement of AI generation efficiency and the mismatch of review resources is sharp. The Graphite report points out that while AI can accelerate code generation (e.g., each developer''s daily PR output increases by 2.3 times), human review capabilities have not improved in tandem, resulting in "more AI-generated PRs" actually reducing the review depth per unit of code. When an e-commerce platform used AI to generate 200+ page components, the security team could only spot-check 5% of the code, directly leading to privilege escalation vulnerabilities in payment interfaces, allowing attackers to obtain others'' order information by modifying request parameters. · Reviewers'' professional capabilities are increasingly unable to match the complexity of AI code. Open-source community statistics show that the proportion of AI-generated code submitters self-checking errors is less than 20%, and receiving reviewers also have capability gaps: an architect at an internet company found that new graduates could not identify the O(n²) complexity hazard caused by nested loops in AI code, and such performance defects triggered system avalanches after the user base exceeded the million level.', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('a741ac74-e055-46f9-a246-4bb4555e2697', '08ab6cce-2975-48f6-991e-93c5d8d711ff', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'Review negligence: The team only verified code syntax correctness through automated testing, without conducting business logic walkthroughs and boundary scenario testing. The refactored code was not checked for consistency with the original comments, and senior engineers did not participate in key module reviews, leading to obvious logical contradictions being overlooked. · Consequences: Platform service interruptions accumulated over 8 hours, user complaints surged by 300%, and although direct economic losses were not disclosed, the cost of manual troubleshooting and system recovery was significant. More seriously, the team took the unconventional measure of "banning the CEO''s account" as a temporary solution, exposing the chaos in the emergency response mechanism.', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('6dc8b258-57b3-41ef-8325-743883fdb96e', '08ab6cce-2975-48f6-991e-93c5d8d711ff', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'Secondly, the lag in organizational culture and management processes is another key factor. Many companies have not correspondingly updated their internal engineering standards, security audit processes, and compliance policies when introducing AI programming tools. GitClear''s research found that in projects adopting Vibe Coding (referring to a rapid AI-assisted agile development model), the vulnerability detection rate is 3.2 times that of traditional development models, with the proportion of low-level errors such as hard-coded keys and lack of input validation as high as 67%. This indicates that without establishing supporting defensive measures, Vibe Coding may instead become a breeding ground for security vulnerabilities. For example, a startup leaked payment API keys during the Vibe Coding process.', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('36da522a-9490-4f84-bc18-866f3f3d7511', '29421184-64c6-41db-903f-467724a087dd', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'Oversights in AI-assisted programming reviews: In-depth analysis of catastrophic consequences caused by vulnerabilities in AI large model-generated code - CSDN Blog', 'other', 'The deepest reason why AI-assisted programming can lead to so many catastrophic consequences lies in the inherent and widespread security and quality defects of AI-generated code. These defects do not appear sporadically but exhibit systemic and large-scale characteristics, making it extremely difficult and unreliable to rely solely on manual review. A large amount of research and test data shows that AI chooses an unsafe path almost half the time when coding, laying the groundwork for subsequent risks. · According to Veracode''s "2025 Gen AI Code Security Report," in tests of over a hundred large AI models, AI-generated code in executing 80', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('1cd3e0fc-5ced-43b3-b928-486b02d4f9a4', '29421184-64c6-41db-903f-467724a087dd', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'The catastrophic cost of AI code generation: In-depth analysis and systemic reflection on human review negligence_ai logic loophole discourse - CSDN blog', 'other', 'Excessive trust in AI-generated content by humans is forming a systemic cognitive bias. Stanford University''s 2025 experiment shows that 79% of developers would misjudge AI-generated unsafe code as safe. This "verification illusion" stems from blind trust in AI output—developers focus more on whether the code "can run" rather than "is it safe," forming a "Vibe Coding" trap: fully relying on AI-generated logic, not reviewing internal implementation, accepting code through superficial functional testing, ultimately accumulating a large amount of "trust debt."', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('8502e8a2-006a-4c4a-89d4-e7f2e2701ace', '29421184-64c6-41db-903f-467724a087dd', 'supporting', 'https://www.secrss.com/articles/80089', 'One-third of AI code enters production environments without review - Security Reference | Cybersecurity Knowledge Base for Decision Makers.', 'other', 'In today''s world where artificial intelligence has become the main developer, the code review mechanism still relies on human effort. A Cloudsmith report reveals that one-third of developers do not conduct pre-deployment reviews of AI-generated code, meaning a large amount of unverified code is being put into use, posing a significant threat to the software supply chain. · Although more than 60% of developers currently state that they only trust AI-generated code after manual review, whether this proportion can be maintained as AI''s code output continues to rise remains a major question.', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('88690d00-b74a-4a8f-9313-ffb61bd8682b', 'ab90d2c2-7c4b-4d27-aee5-3dfc63dae6ca', 'contradicting', 'https://www.53ai.com/news/qianyanjishu/1140.html', 'Challenges faced by AI Agents - 53AI-AI Knowledge Base | Large Model Knowledge Base | Large Model Training | Agent Development', 'other', 'AI Agents face many challenges! Technically, while LLM has improved, models like GPT4 still have many issues when used for AI Agents, such as questionable reliability of interaction interfaces and high costs. Socio-economically, the development of AI Agents may bring challenges such as security privacy, ethical responsibility, and impacts on economic and social employment. Chat ...', 0.5, 0.4, 4, NULL, 0.5);
